import unittest
import loader
import settings


class TestLoadSettings(unittest.TestCase):
    def _defaults(self):
        return dict(settings.DEFAULTS)

    def test_empty_overrides_returns_new_dict_with_defaults(self):
        before = self._defaults()
        result = loader.load_settings({})
        self.assertEqual(result, before)
        self.assertIsNot(result, settings.DEFAULTS)

    def test_valid_overrides_updates_defaults_and_preserves_original(self):
        before = self._defaults()
        overrides = {}
        for k, v in before.items():
            if k == "port":
                overrides[k] = 8080 if v != 8080 else 8081
            elif k == "workers":
                overrides[k] = 4 if v != 4 else 5
            elif isinstance(v, bool):
                overrides[k] = not v
            elif isinstance(v, int):
                overrides[k] = v + 1
            elif isinstance(v, str):
                overrides[k] = v + "_custom"
            elif isinstance(v, float):
                overrides[k] = v + 1.0
        result = loader.load_settings(overrides)
        expected = dict(before)
        expected.update(overrides)
        self.assertEqual(result, expected)
        self.assertEqual(settings.DEFAULTS, before)
        self.assertIsNot(result, settings.DEFAULTS)

    def test_returned_dict_mutation_does_not_modify_defaults(self):
        before = self._defaults()
        result = loader.load_settings({})
        result["port"] = 12345
        self.assertEqual(settings.DEFAULTS, before)

    def test_unknown_key_raises_value_error(self):
        before = self._defaults()
        unknown_key = "__unknown_key_" + "_".join(before.keys())
        with self.assertRaises(ValueError):
            loader.load_settings({unknown_key: 1})
        self.assertEqual(settings.DEFAULTS, before)

    def test_wrong_type_for_each_setting_raises_value_error(self):
        before = self._defaults()
        for k, v in before.items():
            wrong_val = 123 if isinstance(v, str) else "wrong_type"
            with self.assertRaises(ValueError):
                loader.load_settings({k: wrong_val})
        self.assertEqual(settings.DEFAULTS, before)

    def test_bool_rejected_for_int_settings(self):
        before = self._defaults()
        for k, v in before.items():
            if type(v) is int:
                with self.assertRaises(ValueError):
                    loader.load_settings({k: True})
                with self.assertRaises(ValueError):
                    loader.load_settings({k: False})
        self.assertEqual(settings.DEFAULTS, before)

    def test_int_rejected_for_bool_settings(self):
        before = self._defaults()
        for k, v in before.items():
            if type(v) is bool:
                with self.assertRaises(ValueError):
                    loader.load_settings({k: 1})
                with self.assertRaises(ValueError):
                    loader.load_settings({k: 0})
        self.assertEqual(settings.DEFAULTS, before)

    def test_port_valid_boundaries(self):
        res_min = loader.load_settings({"port": 1})
        self.assertEqual(res_min["port"], 1)
        res_max = loader.load_settings({"port": 65535})
        self.assertEqual(res_max["port"], 65535)

    def test_port_below_minimum_raises_value_error(self):
        with self.assertRaises(ValueError):
            loader.load_settings({"port": 0})
        with self.assertRaises(ValueError):
            loader.load_settings({"port": -1})

    def test_port_above_maximum_raises_value_error(self):
        with self.assertRaises(ValueError):
            loader.load_settings({"port": 65536})
        with self.assertRaises(ValueError):
            loader.load_settings({"port": 70000})

    def test_workers_valid_boundary_and_above(self):
        res_min = loader.load_settings({"workers": 1})
        self.assertEqual(res_min["workers"], 1)
        res_more = loader.load_settings({"workers": 8})
        self.assertEqual(res_more["workers"], 8)

    def test_workers_below_minimum_raises_value_error(self):
        with self.assertRaises(ValueError):
            loader.load_settings({"workers": 0})
        with self.assertRaises(ValueError):
            loader.load_settings({"workers": -2})


if __name__ == "__main__":
    unittest.main()

