import unittest
import fmt
import currency


def _get_spec(code):
    entry = currency.CURRENCIES[code]
    if isinstance(entry, tuple):
        if isinstance(entry[0], str):
            return entry[0], entry[1]
        return entry[1], entry[0]
    if isinstance(entry, dict):
        sym = entry.get("symbol") if "symbol" in entry else entry.get("sign")
        dec = (
            entry.get("decimals")
            if "decimals" in entry
            else entry.get("decimal_places", entry.get("minor_units", entry.get("exponent")))
        )
        return sym, dec
    d = entry.__dict__ if hasattr(entry, "__dict__") else {}
    sym = d.get("symbol") if "symbol" in d else d.get("sign")
    dec = (
        d.get("decimals")
        if "decimals" in d
        else d.get("decimal_places", d.get("minor_units", d.get("exponent")))
    )
    if sym is None:
        sym = entry.symbol
    if dec is None:
        dec = entry.decimals
    return sym, dec


def _find_code_by_decimals(target_decimals):
    for code in currency.CURRENCIES:
        sym, dec = _get_spec(code)
        if dec == target_decimals:
            return code, sym, dec
    return None, None, None


class TestFormatMoney(unittest.TestCase):
    def test_unknown_currency_raises_value_error(self):
        with self.assertRaises(ValueError):
            fmt.format_money(100, "UNKNOWN_CODE_XYZ")
        with self.assertRaises(ValueError):
            fmt.format_money(0, "")

    def test_all_currencies_zero_and_small_amounts(self):
        for code in currency.CURRENCIES:
            sym, dec = _get_spec(code)
            if dec == 0:
                self.assertEqual(fmt.format_money(0, code), f"{sym}0")
                self.assertEqual(fmt.format_money(5, code), f"{sym}5")
            else:
                zeros = "0" * dec
                frac = "0" * (dec - 1) + "5"
                self.assertEqual(fmt.format_money(0, code), f"{sym}0.{zeros}")
                self.assertEqual(fmt.format_money(5, code), f"{sym}0.{frac}")

    def test_two_decimal_places_formatting(self):
        code, sym, dec = _find_code_by_decimals(2)
        if code is not None:
            self.assertEqual(fmt.format_money(1, code), f"{sym}0.01")
            self.assertEqual(fmt.format_money(10, code), f"{sym}0.10")
            self.assertEqual(fmt.format_money(99, code), f"{sym}0.99")
            self.assertEqual(fmt.format_money(100, code), f"{sym}1.00")
            self.assertEqual(fmt.format_money(12345, code), f"{sym}123.45")

    def test_zero_decimal_places_no_decimal_point(self):
        code, sym, dec = _find_code_by_decimals(0)
        if code is not None:
            self.assertEqual(fmt.format_money(0, code), f"{sym}0")
            self.assertEqual(fmt.format_money(7, code), f"{sym}7")
            self.assertEqual(fmt.format_money(999, code), f"{sym}999")
            self.assertEqual(fmt.format_money(1000, code), f"{sym}1,000")
            self.assertEqual(fmt.format_money(1234567, code), f"{sym}1,234,567")
            self.assertNotIn(".", fmt.format_money(12345, code))

    def test_three_decimal_places_formatting(self):
        code, sym, dec = _find_code_by_decimals(3)
        if code is not None:
            self.assertEqual(fmt.format_money(0, code), f"{sym}0.000")
            self.assertEqual(fmt.format_money(5, code), f"{sym}0.005")
            self.assertEqual(fmt.format_money(50, code), f"{sym}0.050")
            self.assertEqual(fmt.format_money(1000, code), f"{sym}1.000")
            self.assertEqual(fmt.format_money(1234567, code), f"{sym}1,234.567")

    def test_thousands_grouping(self):
        for code in currency.CURRENCIES:
            sym, dec = _get_spec(code)
            scale = 10 ** dec
            frac_str = ("." + "0" * dec) if dec > 0 else ""
            self.assertEqual(fmt.format_money(999 * scale, code), f"{sym}999{frac_str}")
            self.assertEqual(fmt.format_money(1000 * scale, code), f"{sym}1,000{frac_str}")
            self.assertEqual(fmt.format_money(1234567 * scale, code), f"{sym}1,234,567{frac_str}")
            self.assertEqual(
                fmt.format_money(1000000000 * scale, code),
                f"{sym}1,000,000,000{frac_str}",
            )

    def test_negative_amounts(self):
        for code in currency.CURRENCIES:
            sym, dec = _get_spec(code)
            scale = 10 ** dec
            if dec == 0:
                self.assertEqual(fmt.format_money(-1, code), f"-{sym}1")
                self.assertEqual(fmt.format_money(-1234, code), f"-{sym}1,234")
            else:
                frac_one = "0" * (dec - 1) + "1"
                frac_fifty = "5" + "0" * (dec - 1)
                self.assertEqual(fmt.format_money(-1, code), f"-{sym}0.{frac_one}")
                self.assertEqual(
                    fmt.format_money(-(1234 * scale + 5 * (10 ** (dec - 1))), code),
                    f"-{sym}1,234.{frac_fifty}",
                )
