import unittest
import bounds


class TestBounds(unittest.TestCase):
    def test_clamp_within_range(self):
        self.assertEqual(bounds.clamp(5.0, 0.0, 10.0), 5.0)
        self.assertEqual(bounds.clamp(0.0, -5.0, 5.0), 0.0)
        self.assertEqual(bounds.clamp(-3.5, -10.0, -1.0), -3.5)

    def test_clamp_below_lower_bound(self):
        self.assertEqual(bounds.clamp(-2.0, 0.0, 10.0), 0.0)
        self.assertEqual(bounds.clamp(-15.5, -10.0, -5.0), -10.0)

    def test_clamp_above_upper_bound(self):
        self.assertEqual(bounds.clamp(12.0, 0.0, 10.0), 10.0)
        self.assertEqual(bounds.clamp(0.0, -10.0, -5.0), -5.0)

    def test_clamp_at_lower_bound(self):
        self.assertEqual(bounds.clamp(0.0, 0.0, 10.0), 0.0)
        self.assertEqual(bounds.clamp(-5.0, -5.0, 5.0), -5.0)

    def test_clamp_at_upper_bound(self):
        self.assertEqual(bounds.clamp(10.0, 0.0, 10.0), 10.0)
        self.assertEqual(bounds.clamp(5.0, -5.0, 5.0), 5.0)

    def test_clamp_degenerate_range(self):
        self.assertEqual(bounds.clamp(3.0, 3.0, 3.0), 3.0)
        self.assertEqual(bounds.clamp(1.0, 3.0, 3.0), 3.0)
        self.assertEqual(bounds.clamp(5.0, 3.0, 3.0), 3.0)


