import unittest
import fmt
import currency


class TestFormatMoney(unittest.TestCase):
    def _find_currency_with_decimals(self, target_decimals):
        for code, info in currency.CURRENCIES.items():
            if isinstance(info, tuple) and len(info) >= 2:
                symbol, decimals = info[0], info[1]
                if isinstance(decimals, int) and decimals == target_decimals:
                    return code, symbol, decimals
                if isinstance(symbol, int) and symbol == target_decimals:
                    return code, decimals, symbol
            elif isinstance(info, dict):
                decimals = info.get("decimals", info.get("decimal_places", info.get("exponent")))
                symbol = info.get("symbol")
                if decimals == target_decimals and symbol is not None:
                    return code, symbol, decimals
            else:
                for dec_attr in ("decimals", "decimal_places", "exponent"):
                    if hasattr(info, dec_attr) and getattr(info, dec_attr) == target_decimals:
                        return code, getattr(info, "symbol"), target_decimals
        return None

    def _extract_info(self, info):
        if isinstance(info, tuple):
            if isinstance(info[0], str):
                return info[0], info[1]
            return info[1], info[0]
        if isinstance(info, dict):
            for k in ("decimals", "decimal_places", "exponent"):
                if k in info:
                    return info["symbol"], info[k]
        for k in ("decimals", "decimal_places", "exponent"):
            if hasattr(info, k):
                return getattr(info, "symbol"), getattr(info, k)
        raise RuntimeError("Unknown currency structure")

    def _expected_format(self, minor_units, symbol, decimals):
        sign = "-" if minor_units < 0 else ""
        abs_units = abs(minor_units)
        if decimals == 0:
            whole = abs_units
            return f"{sign}{symbol}{whole:,}"
        divisor = 10 ** decimals
        whole, frac = divmod(abs_units, divisor)
        return f"{sign}{symbol}{whole:,}.{frac:0{decimals}d}"

    def test_zero_amount(self):
        for code, info in currency.CURRENCIES.items():
            symbol, decimals = self._extract_info(info)
            expected = self._expected_format(0, symbol, decimals)
            self.assertEqual(fmt.format_money(0, code), expected)

    def test_small_positive_amounts_leading_zeros_in_fraction(self):
        for code, info in currency.CURRENCIES.items():
            symbol, decimals = self._extract_info(info)
            for amount in (1, 5, 10, 99):
                expected = self._expected_format(amount, symbol, decimals)
                self.assertEqual(fmt.format_money(amount, code), expected)

    def test_thousands_grouping(self):
        for code, info in currency.CURRENCIES.items():
            symbol, decimals = self._extract_info(info)
            scale = 10 ** decimals
            for whole in (999, 1000, 1234, 999999, 1000000, 1234567890):
                minor = whole * scale + (50 if decimals >= 2 else (5 if decimals == 1 else 0))
                expected = self._expected_format(minor, symbol, decimals)
                self.assertEqual(fmt.format_money(minor, code), expected)

    def test_zero_decimal_currency_has_no_decimal_point(self):
        found = self._find_currency_with_decimals(0)
        if found is not None:
            code, symbol, _ = found
            self.assertEqual(fmt.format_money(0, code), f"{symbol}0")
            self.assertEqual(fmt.format_money(500, code), f"{symbol}500")
            self.assertEqual(fmt.format_money(1234567, code), f"{symbol}1,234,567")
            self.assertEqual(fmt.format_money(-1234, code), f"-{symbol}1,234")
            self.assertNotIn(".", fmt.format_money(1234, code))

    def test_negative_amounts_place_minus_before_symbol(self):
        for code, info in currency.CURRENCIES.items():
            symbol, decimals = self._extract_info(info)
            scale = 10 ** decimals
            for minor in (-1, -scale, -(1234 * scale + (50 if decimals >= 2 else 0)), -(1000000 * scale)):
                result = fmt.format_money(minor, code)
                expected = self._expected_format(minor, symbol, decimals)
                self.assertEqual(result, expected)
                self.assertTrue(result.startswith(f"-{symbol}"))

    def test_unknown_currency_code_raises_value_error(self):
        for bad_code in ("", "UNKNOWN", "ZZZ", "invalid", "usd"):
            if bad_code not in currency.CURRENCIES:
                with self.assertRaises(ValueError):
                    fmt.format_money(100, bad_code)


if __name__ == "__main__":
    unittest.main()
