import unittest
import seqs


class TestDedupe(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(seqs.dedupe([]), [])

    def test_single_item(self):
        self.assertEqual(seqs.dedupe([1]), [1])

    def test_no_duplicates(self):
        self.assertEqual(seqs.dedupe([3, 1, 2]), [3, 1, 2])

    def test_all_duplicates(self):
        self.assertEqual(seqs.dedupe([7, 7, 7, 7]), [7])

    def test_adjacent_duplicates(self):
        self.assertEqual(seqs.dedupe([1, 1, 2, 2, 3, 3]), [1, 2, 3])

    def test_non_adjacent_duplicates_preserves_first_occurrence_order(self):
        self.assertEqual(seqs.dedupe([3, 1, 2, 1, 3, 4, 2]), [3, 1, 2, 4])

    def test_strings_preserves_order(self):
        self.assertEqual(
            seqs.dedupe(["b", "a", "b", "c", "a"]),
            ["b", "a", "c"],
        )

    def test_duplicate_at_start_and_end(self):
        self.assertEqual(seqs.dedupe(["x", "y", "z", "x"]), ["x", "y", "z"])

    def test_does_not_sort_result(self):
        self.assertEqual(seqs.dedupe([10, 5, 10, 1, 5]), [10, 5, 1])


if __name__ == "__main__":
